#!/usr/bin/env python3
"""Build roqsim's Neobotix arm cabinet (``mpo_cabinet``) from ``neobotix/mp_utils``.

The cabinet is what a UR stands on when Neobotix puts one on an MPO-500 (their MMO-500): a box on the
platform's deck that houses the arm's control box, with the arm bolted to its top plate. It is a
**riser**, not a robot: no joints, no actuators -- ``spawn_arm``'s ``mount.riser`` welds it between the
base's body and the arm, so the arm stands on a real collider at the height the robot's does.

Source: ``mp_components/urdf/arm/mpo_cabinet_macro.xacro`` (link ``<name>_link``, mass 2 kg and the
vendor's inertia, visual and collision both the ``cabinet_ac`` / ``cabinet_dc`` Collada at 1/1000
scale yawed -pi/2) and ``mp_components/meshes``. The AC variant (the cabinet for the UR's AC control
box) is the default the vendor's macro picks; the DC one differs in its front panel only.

The model's frame is the macro's ``<name>_link``: z up from the cabinet's floor, the top plate at
z 0.419, and the vendor puts the UR's ``base_link`` at (0.133, 0, 0.416) in it.

Collision is ONE box, the mesh's bounds above the base's top cover (``COLLISION_FLOOR``): the cabinet
is a closed box and the arm's base stands on its top, so a hull would only add vertices. Visual is the
mesh, split per material by ``dae2obj`` and cut at the same floor.

Usage::

    python external/convert/build_mpo_cabinet_mjcf.py           # (re)generate the model
    python external/convert/build_mpo_cabinet_mjcf.py --check   # fail if the committed one differs

Needs ``pycollada`` (dae2obj) and network access or ``external/sources/mp_utils`` at the commit.
"""

from __future__ import annotations

import argparse
import json
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

import numpy as np
from sources import resolve_source

ROOT = Path(__file__).resolve().parents[2]
PKG = ROOT / "roqsim_mobile_manipulation/src/roqsim_mobile_manipulation/models/mpo_cabinet"
URL = "https://github.com/neobotix/mp_utils.git"
COMMIT = "c4ba0a7601a9682dd794fe06e068685528bfded5"  # branch jazzy
VARIANT = "cabinet_ac"
#: mpo_cabinet_macro.xacro: <mass value="2"/>, inertia ixx 0.457072, iyy 0.23616, izz 0.686.
MASS = 2.0
DIAGINERTIA = (0.457072, 0.23616, 0.686)
#: The macro's visual/collision origin: rpy 0 0 -1.5708, mesh scale 0.001.
YAW = -1.5708
SCALE = 0.001
#: Where the collider starts, in the cabinet's frame. The vendor stands the cabinet at base_link
#: z 0.35 (neo_mpo_500-2 mpo_500.urdf.xacro) while the MPO-500's top cover rises to z 0.386, so the
#: cabinet's lowest 36 mm are inside the base's body: nothing can touch them, and the base's own
#: cover shields them from the scanners, whose plane (z 0.372) passes there. A collider reaching down
#: into that band is seen by both scanners as an obstacle a few decimetres away -- a robot that sees
#: itself and stops (roqsim_mobile's mpo_500 models the base's body as one convex hull, which does
#: not occlude the band). Above it the box is the mesh's bounds.
COLLISION_FLOOR = 0.386 - 0.35
#: The visual mesh is cut at the same plane: roqsim's lidar casts against visual triangles too, and
#: the part below the cover is inside the base's body, so it is neither seen nor seeable.

TEMPLATE = """<mujoco model="mpo_cabinet">
  <!--
    Neobotix's arm cabinet for the MPO-500: the riser a UR stands on (spawn_arm mount.riser).

    GENERATED by external/convert/build_mpo_cabinet_mjcf.py from neobotix/mp_utils @ {commit}
    (mp_components; Apache-2.0 - see mpo_cabinet_LICENSE). Do not hand-edit: re-run the generator.

    Frame: the vendor's cabinet_link. Floor of the cabinet at z 0, its top plate at z {top:.3f}; the
    vendor mounts the UR's base_link at (0.133, 0, 0.416). Collision is one box, the mesh's bounds;
    collision and visual both start at z {floor:.3f}, where the MPO-500's top cover is.
  -->
  <compiler angle="radian" meshdir="meshes" autolimits="true"/>
  <default>
    <default class="mpo_cabinet">
      <default class="visual">
        <geom type="mesh" contype="0" conaffinity="0" group="2"/>
      </default>
      <default class="collision">
        <geom type="box" group="3" rgba="0.6 0.1 0.1 0.35"/>
      </default>
    </default>
  </default>
  <asset>
{materials}{meshes}  </asset>
  <worldbody>
    <body name="cabinet_link" childclass="mpo_cabinet">
      <inertial pos="0 0 {com_z:.4f}" mass="{mass}" diaginertia="{inertia}"/>
{visuals}      <geom class="collision" name="cabinet_collision" pos="{centre}" size="{half}"/>
      <site name="arm_mount" pos="0.133 0 0.416" quat="0.7071068 0 0 -0.7071068" size="0.01" rgba="0 0 0 0"/>
    </body>
  </worldbody>
</mujoco>
"""


def _write_cut(src: Path, dst: Path, floor: float) -> None:
    """*src* with everything below z = *floor* (its own units) clipped away, as an OBJ without normals.

    Each triangle is clipped against the plane (Sutherland-Hodgman, one plane): kept whole above it,
    dropped below it, and cut where it crosses, so the walls end exactly at the floor.
    """
    verts, faces = [], []
    for line in src.read_text().splitlines():
        parts = line.split()
        if parts and parts[0] == "v":
            verts.append(np.array([float(x) for x in parts[1:4]]))
        elif parts and parts[0] == "f":
            faces.append([int(x.split("/")[0]) - 1 for x in parts[1:4]])
    out_v, out_f = [], []
    for face in faces:
        poly = [verts[i] for i in face]
        kept = []
        for a, b in zip(poly, poly[1:] + poly[:1], strict=True):
            a_in, b_in = a[2] >= floor, b[2] >= floor
            if a_in:
                kept.append(a)
            if a_in != b_in:
                t = (floor - a[2]) / (b[2] - a[2])
                kept.append(a + t * (b - a))
        for k in range(1, len(kept) - 1):  # fan-triangulate the clipped polygon
            base = len(out_v)
            out_v += [kept[0], kept[k], kept[k + 1]]
            out_f.append((base, base + 1, base + 2))
    with open(dst, "w") as f:
        for x, y, z in out_v:
            f.write(f"v {x:.6f} {y:.6f} {z:.6f}\n")
        for a, b, c in out_f:
            f.write(f"f {a + 1} {b + 1} {c + 1}\n")


def build(source: Path, out: Path) -> None:
    with tempfile.TemporaryDirectory() as tmp:
        staged = Path(tmp) / "dae"
        staged.mkdir()
        shutil.copy2(source / "mp_components/meshes" / f"{VARIANT}.dae", staged)
        raw = Path(tmp) / "obj"
        subprocess.run(
            [sys.executable, str(Path(__file__).parent / "dae2obj.py"), str(staged), str(raw)],
            check=True,
        )
        palette = json.loads((raw / "materials.json").read_text())[VARIANT]
        meshes_dir = out / "meshes"
        if meshes_dir.exists():
            shutil.rmtree(meshes_dir)
        meshes_dir.mkdir(parents=True)
        verts = []
        for sub, _ in palette:
            _write_cut(raw / f"{sub}.obj", meshes_dir / f"{sub}.obj", COLLISION_FLOOR / SCALE)
            verts += [
                list(map(float, line.split()[1:4]))
                for line in (raw / f"{sub}.obj").read_text().splitlines()
                if line.startswith("v ")
            ]
    v = np.asarray(verts) * SCALE
    c, s = np.cos(YAW), np.sin(YAW)
    v = v @ np.array([[c, -s, 0.0], [s, c, 0.0], [0.0, 0.0, 1.0]]).T
    lo, hi = v.min(axis=0), v.max(axis=0)
    lo[2] = max(lo[2], COLLISION_FLOOR)
    quat = f"{np.cos(YAW / 2):.7f} 0 0 {np.sin(YAW / 2):.7f}"
    materials = "".join(
        f'    <material name="{sub}_mat" rgba="{r:g} {g:g} {b:g} 1"/>\n'
        for sub, (r, g, b) in palette
    )
    meshes = "".join(
        f'    <mesh name="{sub}" file="{sub}.obj" scale="{SCALE:g} {SCALE:g} {SCALE:g}" '
        f'inertia="shell"/>\n'
        for sub, _ in palette
    )
    visuals = "".join(
        f'      <geom class="visual" mesh="{sub}" material="{sub}_mat" quat="{quat}"/>\n'
        for sub, _ in palette
    )
    (out / "mpo_cabinet.xml").write_text(
        TEMPLATE.format(
            commit=COMMIT,
            floor=COLLISION_FLOOR,
            top=hi[2],
            materials=materials,
            meshes=meshes,
            visuals=visuals,
            com_z=(v.min(axis=0)[2] + hi[2]) / 2,
            mass=f"{MASS:g}",
            inertia=" ".join(f"{x:g}" for x in DIAGINERTIA),
            centre=" ".join(f"{x:.4f}" for x in (lo + hi) / 2),
            half=" ".join(f"{x:.4f}" for x in (hi - lo) / 2),
        )
    )
    shutil.copy2(source / "mp_components/LICENSE", out / "mpo_cabinet_LICENSE")


def main() -> int:
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument("--check", action="store_true", help="fail if the committed model differs")
    args = parser.parse_args()
    source = resolve_source("mp_utils", URL, COMMIT)
    if not args.check:
        PKG.mkdir(parents=True, exist_ok=True)
        build(source, PKG)
        print(f"wrote {PKG}")
        return 0
    with tempfile.TemporaryDirectory() as tmp:
        build(source, Path(tmp))
        same = (Path(tmp) / "mpo_cabinet.xml").read_text() == (PKG / "mpo_cabinet.xml").read_text()
    print("mpo_cabinet: up to date" if same else "mpo_cabinet: DIFFERS from the generator's output")
    return 0 if same else 1


if __name__ == "__main__":
    sys.exit(main())
